        idea: 'אותו רעיון כמו בקארו-קאן: ...c6 תומך ב-d5, ורץ המשבצות הלבנות של שחור יוצא ל-f5 לפני ...e6 — כך הוא לא נכלא. שחור לוקח את הרגלי ב-c4, ואחרי a4 הרץ ב-f5 מונע מלבן לשחק e4 בנוחות. שחור מפתח הכל ומצריח בבטחה.',
